    <>
      <button type="button" onClick={trigger}>Animate</button>
      <div className={"t-input-wrap" + (error ? " is-error" : "")}>
        <div
          ref={inputRef}
          className={"t-input" + (error ? " is-error" : "")}
          onInput={cancel}
